-- الصفحة الرئيسية الجديدة: نص الهيرو، سطر الثقة (بدل الشارات)، وخطوات الاشتراك + الصيغة المحايدة في النصوص المحفوظة.
-- يحدّث الحقول المذكورة فقط ويحتفظ بباقي إعدادات الهيرو (الشعار اللفظي وغيره). إعادة التشغيل آمنة (نفس النتيجة).
BEGIN;
UPDATE site_settings
   SET value = value || jsonb_build_object(
         'title', 'برنامج مبني عليك،',
         'title_tail', 'مو جدول جاهز',
         'lead', 'تدريب وتغذية مخصصة لهدفك ومستواك، مع مراجعة وتعديل أسبوعي من الكوتش ساره.'),
       updated_at = now()
 WHERE key = 'hero';
-- صورة الواجهة المرفوعة (فيها إطارات الجوال) تُستبدل بلقطة «برنامجي» الحقيقية. الصورة نفسها تبقى في «الصور» ويمكن اختيارها مرة ثانية.
UPDATE site_settings SET value = jsonb_build_object('media_id', NULL), updated_at = now() WHERE key = 'hero_image';
UPDATE site_settings
   SET value = '["أدرّب منذ 2017", "ماجستير تدريب رياضي · جامعة ستيرلنق", "ضمان استرجاع المبلغ بشروط"]'::jsonb, updated_at = now()
 WHERE key = 'badges';
UPDATE site_settings
   SET value = '[
     {"title": "اختيار البرنامج وتعبئة الاستبيان", "body": "اختيار الباقة والمدة، ثم استبيان قصير عن الهدف والمستوى والأيام المتاحة وأي إصابة."},
     {"title": "تحويل المبلغ", "body": "بعد الاستبيان يظهر رقم الطلب وبيانات الحساب. التحويل ثم رفع صورة الإيصال من صفحة الطلب."},
     {"title": "استلام البرنامج والبدء", "body": "بعد التحقق من التحويل أتواصل خلال 48 ساعة عمل، ويُسلَّم ملف البرنامج وتبدأ المتابعة."}
   ]'::jsonb, updated_at = now()
 WHERE key = 'how_steps';
-- ===== الصيغة المحايدة في النصوص المحفوظة بقاعدة البيانات (الأسئلة الشائعة، السياسات، صفحة المدربة، أسئلة الاستبيان المضافة) =====
-- replace يغيّر العبارة إذا وُجدت فقط، فأي تعديل سابق من لوحة الإدارة يبقى كما هو. إعادة التشغيل آمنة.
UPDATE faqs SET question = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(question, 'ترسل مراجعتك الأسبوعية في يوم المراجعة، وأرد عليك بتعديلات', 'المراجعة الأسبوعية تُرسل في يوم المراجعة، وأرد عليها بتعديلات'), 'أنا مبتدئ تماماً، هل يناسبني؟', 'هل يناسب المبتدئين تماماً؟'), 'وتقدر ترسل مقاطع أدائك لتصحيح التكنيك', 'وبإمكانك إرسال مقاطع الأداء لتصحيح التكنيك'), 'تحدد في النموذج الأدوات المتوفرة عندك', 'النموذج فيه خانة للأدوات المتوفرة'), 'أول ما ترسل الاستبيان يظهر لك رقم طلبك والمبلغ وبيانات الحساب. حوّل المبلغ وارفع صورة الإيصال من صفحة طلبك', 'أول ما يُرسل الاستبيان يظهر رقم الطلب والمبلغ وبيانات الحساب. تحويل المبلغ ثم رفع صورة الإيصال من صفحة الطلب'), 'يرجع لك المبلغ كاملاً', 'يُسترجع المبلغ كاملاً'), 'إذا كان اشتراكك 3 أشهر تحصل على 3 أشهر إضافية مجاناً', 'اشتراك 3 أشهر يحصل على 3 أشهر إضافية مجاناً'), 'جميع الجداول لك مدى الحياة وتقدر تعدّل عليها', 'جميع الجداول لك مدى الحياة والتعديل عليها متاح'), 'ما أرسل لك جدول وأتركك.', 'ما أرسل جدول وأترك المتابعة.'), 'عشان تبدأ وأنت فاهم وش تسوي وليش', 'عشان تكون البداية بفهم كامل: وش نسوي وليش'), 'أقول لك بصراحة', 'أقولها بصراحة'), 'وإذا ما التزمت؟', 'وإذا ما صار التزام؟'), 'اللي يؤمن إن التمرين أسلوب حياة', 'كل من يؤمن إن التمرين أسلوب حياة'), 'شوف باقة القيمرز ←', 'باقة القيمرز ←'), 'ويمكنه التعديل عليها', 'والتعديل عليها متاح'), 'تقدر تطلب نسخة من بياناتك', 'يحق طلب نسخة من البيانات'), 'تختار بنفسك طريقة ظهور اسمك:', 'طريقة ظهور الاسم اختيارية:'), 'تقدر تطلب إخفاء تقييمك', 'يحق طلب إخفاء التقييم'), 'وتقدر ترفض فلا نقيس زيارتك', 'والرفض متاح فلا تُقاس الزيارة'), 'اذكر نوع اللعبة الي تلعبها بشكل محترف', 'نوع اللعبة الاحترافية'), 'اذكر نوع اللعبة اللي تلعبها بشكل محترف', 'نوع اللعبة الاحترافية'), answer = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(answer, 'ترسل مراجعتك الأسبوعية في يوم المراجعة، وأرد عليك بتعديلات', 'المراجعة الأسبوعية تُرسل في يوم المراجعة، وأرد عليها بتعديلات'), 'أنا مبتدئ تماماً، هل يناسبني؟', 'هل يناسب المبتدئين تماماً؟'), 'وتقدر ترسل مقاطع أدائك لتصحيح التكنيك', 'وبإمكانك إرسال مقاطع الأداء لتصحيح التكنيك'), 'تحدد في النموذج الأدوات المتوفرة عندك', 'النموذج فيه خانة للأدوات المتوفرة'), 'أول ما ترسل الاستبيان يظهر لك رقم طلبك والمبلغ وبيانات الحساب. حوّل المبلغ وارفع صورة الإيصال من صفحة طلبك', 'أول ما يُرسل الاستبيان يظهر رقم الطلب والمبلغ وبيانات الحساب. تحويل المبلغ ثم رفع صورة الإيصال من صفحة الطلب'), 'يرجع لك المبلغ كاملاً', 'يُسترجع المبلغ كاملاً'), 'إذا كان اشتراكك 3 أشهر تحصل على 3 أشهر إضافية مجاناً', 'اشتراك 3 أشهر يحصل على 3 أشهر إضافية مجاناً'), 'جميع الجداول لك مدى الحياة وتقدر تعدّل عليها', 'جميع الجداول لك مدى الحياة والتعديل عليها متاح'), 'ما أرسل لك جدول وأتركك.', 'ما أرسل جدول وأترك المتابعة.'), 'عشان تبدأ وأنت فاهم وش تسوي وليش', 'عشان تكون البداية بفهم كامل: وش نسوي وليش'), 'أقول لك بصراحة', 'أقولها بصراحة'), 'وإذا ما التزمت؟', 'وإذا ما صار التزام؟'), 'اللي يؤمن إن التمرين أسلوب حياة', 'كل من يؤمن إن التمرين أسلوب حياة'), 'شوف باقة القيمرز ←', 'باقة القيمرز ←'), 'ويمكنه التعديل عليها', 'والتعديل عليها متاح'), 'تقدر تطلب نسخة من بياناتك', 'يحق طلب نسخة من البيانات'), 'تختار بنفسك طريقة ظهور اسمك:', 'طريقة ظهور الاسم اختيارية:'), 'تقدر تطلب إخفاء تقييمك', 'يحق طلب إخفاء التقييم'), 'وتقدر ترفض فلا نقيس زيارتك', 'والرفض متاح فلا تُقاس الزيارة'), 'اذكر نوع اللعبة الي تلعبها بشكل محترف', 'نوع اللعبة الاحترافية'), 'اذكر نوع اللعبة اللي تلعبها بشكل محترف', 'نوع اللعبة الاحترافية');
UPDATE policies SET body = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(body, 'ترسل مراجعتك الأسبوعية في يوم المراجعة، وأرد عليك بتعديلات', 'المراجعة الأسبوعية تُرسل في يوم المراجعة، وأرد عليها بتعديلات'), 'أنا مبتدئ تماماً، هل يناسبني؟', 'هل يناسب المبتدئين تماماً؟'), 'وتقدر ترسل مقاطع أدائك لتصحيح التكنيك', 'وبإمكانك إرسال مقاطع الأداء لتصحيح التكنيك'), 'تحدد في النموذج الأدوات المتوفرة عندك', 'النموذج فيه خانة للأدوات المتوفرة'), 'أول ما ترسل الاستبيان يظهر لك رقم طلبك والمبلغ وبيانات الحساب. حوّل المبلغ وارفع صورة الإيصال من صفحة طلبك', 'أول ما يُرسل الاستبيان يظهر رقم الطلب والمبلغ وبيانات الحساب. تحويل المبلغ ثم رفع صورة الإيصال من صفحة الطلب'), 'يرجع لك المبلغ كاملاً', 'يُسترجع المبلغ كاملاً'), 'إذا كان اشتراكك 3 أشهر تحصل على 3 أشهر إضافية مجاناً', 'اشتراك 3 أشهر يحصل على 3 أشهر إضافية مجاناً'), 'جميع الجداول لك مدى الحياة وتقدر تعدّل عليها', 'جميع الجداول لك مدى الحياة والتعديل عليها متاح'), 'ما أرسل لك جدول وأتركك.', 'ما أرسل جدول وأترك المتابعة.'), 'عشان تبدأ وأنت فاهم وش تسوي وليش', 'عشان تكون البداية بفهم كامل: وش نسوي وليش'), 'أقول لك بصراحة', 'أقولها بصراحة'), 'وإذا ما التزمت؟', 'وإذا ما صار التزام؟'), 'اللي يؤمن إن التمرين أسلوب حياة', 'كل من يؤمن إن التمرين أسلوب حياة'), 'شوف باقة القيمرز ←', 'باقة القيمرز ←'), 'ويمكنه التعديل عليها', 'والتعديل عليها متاح'), 'تقدر تطلب نسخة من بياناتك', 'يحق طلب نسخة من البيانات'), 'تختار بنفسك طريقة ظهور اسمك:', 'طريقة ظهور الاسم اختيارية:'), 'تقدر تطلب إخفاء تقييمك', 'يحق طلب إخفاء التقييم'), 'وتقدر ترفض فلا نقيس زيارتك', 'والرفض متاح فلا تُقاس الزيارة'), 'اذكر نوع اللعبة الي تلعبها بشكل محترف', 'نوع اللعبة الاحترافية'), 'اذكر نوع اللعبة اللي تلعبها بشكل محترف', 'نوع اللعبة الاحترافية');
UPDATE policies SET body = '- يُقصد بالمتدرب كل من يشترك في الخدمة من الجنسين.' || E'\n' || body WHERE slug = 'terms' AND body NOT LIKE '%يُقصد بالمتدرب%';
UPDATE site_settings SET value = (replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(value::text, 'ترسل مراجعتك الأسبوعية في يوم المراجعة، وأرد عليك بتعديلات', 'المراجعة الأسبوعية تُرسل في يوم المراجعة، وأرد عليها بتعديلات'), 'أنا مبتدئ تماماً، هل يناسبني؟', 'هل يناسب المبتدئين تماماً؟'), 'وتقدر ترسل مقاطع أدائك لتصحيح التكنيك', 'وبإمكانك إرسال مقاطع الأداء لتصحيح التكنيك'), 'تحدد في النموذج الأدوات المتوفرة عندك', 'النموذج فيه خانة للأدوات المتوفرة'), 'أول ما ترسل الاستبيان يظهر لك رقم طلبك والمبلغ وبيانات الحساب. حوّل المبلغ وارفع صورة الإيصال من صفحة طلبك', 'أول ما يُرسل الاستبيان يظهر رقم الطلب والمبلغ وبيانات الحساب. تحويل المبلغ ثم رفع صورة الإيصال من صفحة الطلب'), 'يرجع لك المبلغ كاملاً', 'يُسترجع المبلغ كاملاً'), 'إذا كان اشتراكك 3 أشهر تحصل على 3 أشهر إضافية مجاناً', 'اشتراك 3 أشهر يحصل على 3 أشهر إضافية مجاناً'), 'جميع الجداول لك مدى الحياة وتقدر تعدّل عليها', 'جميع الجداول لك مدى الحياة والتعديل عليها متاح'), 'ما أرسل لك جدول وأتركك.', 'ما أرسل جدول وأترك المتابعة.'), 'عشان تبدأ وأنت فاهم وش تسوي وليش', 'عشان تكون البداية بفهم كامل: وش نسوي وليش'), 'أقول لك بصراحة', 'أقولها بصراحة'), 'وإذا ما التزمت؟', 'وإذا ما صار التزام؟'), 'اللي يؤمن إن التمرين أسلوب حياة', 'كل من يؤمن إن التمرين أسلوب حياة'), 'شوف باقة القيمرز ←', 'باقة القيمرز ←'), 'ويمكنه التعديل عليها', 'والتعديل عليها متاح'), 'تقدر تطلب نسخة من بياناتك', 'يحق طلب نسخة من البيانات'), 'تختار بنفسك طريقة ظهور اسمك:', 'طريقة ظهور الاسم اختيارية:'), 'تقدر تطلب إخفاء تقييمك', 'يحق طلب إخفاء التقييم'), 'وتقدر ترفض فلا نقيس زيارتك', 'والرفض متاح فلا تُقاس الزيارة'), 'اذكر نوع اللعبة الي تلعبها بشكل محترف', 'نوع اللعبة الاحترافية'), 'اذكر نوع اللعبة اللي تلعبها بشكل محترف', 'نوع اللعبة الاحترافية'))::jsonb, updated_at = now() WHERE key IN ('about', 'intake_questions');
SELECT (SELECT count(*) FROM faqs WHERE answer LIKE '%تقدر%' OR question LIKE '%مبتدئ تماماً، هل%') AS faq_left,
       (SELECT count(*) FROM policies WHERE body LIKE '%تقدر تطلب%') AS policies_left,
       (SELECT count(*) FROM policies WHERE slug = 'terms' AND body LIKE '%يُقصد بالمتدرب%') AS terms_line;
COMMIT;
